                ? (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      onOpenHand(hit.payout_id);
                    }
                  }
                : undefined
            }

onKeyDown={(e) => {
            // Half a tablist is worse than none: a reader announced "tab 1 of 2"
            // and the arrow keys did nothing.
            if (e.key === 'ArrowLeft' || e.key === 'Home') {
              e.preventDefault();
              setTab('qualifying');
            } else if (e.key === 'ArrowRight' || e.key === 'End') {
              e.preventDefault();
              setTab('payout');
            }
          }}

onClick={onClick}; onKeyDown={
        onClick
          ? (e) => {
              // preventDefault first: Space on a div activates AND scrolls the
              // page underneath. BBJRecentHits already gets this right.
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onClick();
              }
            }
          : undefined
      }

onWheel={onWheel}; onKeyDown={(e) => {
          if (e.key === 'ArrowRight') {
            e.preventDefault();
            nudge(1);
          } else if (e.key === 'ArrowLeft') {
            e.preventDefault();
            nudge(-1);
          }
        }}

onClick={() => onChange(item.value)}; onKeyDown={(event) => {
            if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return;
            event.preventDefault();
            const current = items.findIndex((candidate) => candidate.value === item.value);
            const next =
              event.key === 'Home'
                ? 0
                : event.key === 'End'
                  ? items.length - 1
                  : event.key === 'ArrowRight'
                    ? (current + 1) % items.length
                    : (current - 1 + items.length) % items.length;
            onChange(items[next].value);
            const tablist = event.currentTarget.parentElement;
            window.requestAnimationFrame(() => {
              tablist?.querySelectorAll<HTMLButtonElement>('[role="tab"]')[next]?.focus();
            });
          }}

onKeyDown={(event) => {
        if (event.key === 'Escape') {
          event.preventDefault();
          onClose();
          return;
        }
        if (event.key !== 'Tab') return;
        const focusable = dialogRef.current?.querySelectorAll<HTMLElement>(
          'button:not(:disabled), input:not(:disabled), select:not(:disabled), [href], [tabindex]:not([tabindex="-1"])'
        );
        if (!focusable?.length) return;
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      }}

